// MOCK DATA: Use Case 1 - Morning disruption (cancelled RE4)
// This simulates the transport.rest API response

const mockTransportResponse = {
  journeys: [
    {
      legs: [{
        departure: '2026-01-31T07:34:00+01:00',
        arrival: '2026-01-31T08:49:00+01:00',
        plannedDeparture: '2026-01-31T07:34:00+01:00',
        plannedArrival: '2026-01-31T08:49:00+01:00',
        cancelled: true,
        departureDelay: 0,
        line: { name: 'RE4', operator: { name: 'DB Regio' } },
        origin: { name: 'Hamburg Hbf' },
        destination: { name: 'Bremen Hbf' },
        remarks: [{ text: 'Cancelled due to operational disruption (signal failure).' }]
      }]
    },
    {
      legs: [{
        departure: '2026-01-31T08:18:00+01:00',
        arrival: '2026-01-31T09:36:00+01:00',
        plannedDeparture: '2026-01-31T08:06:00+01:00',
        plannedArrival: '2026-01-31T09:21:00+01:00',
        cancelled: false,
        departureDelay: 720,
        line: { name: 'RE4', operator: { name: 'DB Regio' } },
        origin: { name: 'Hamburg Hbf' },
        destination: { name: 'Bremen Hbf' },
        remarks: [{ text: 'Delay likely impacts arrival time.' }]
      }]
    },
    {
      legs: [{
        departure: '2026-01-31T08:34:00+01:00',
        arrival: '2026-01-31T09:49:00+01:00',
        plannedDeparture: '2026-01-31T08:34:00+01:00',
        plannedArrival: '2026-01-31T09:49:00+01:00',
        cancelled: false,
        departureDelay: 0,
        line: { name: 'RE4', operator: { name: 'DB Regio' } },
        origin: { name: 'Hamburg Hbf' },
        destination: { name: 'Bremen Hbf' },
        remarks: []
      }]
    }
  ]
};

return mockTransportResponse;

// MOCK DATA: Weather for Use Case 1
// Simulates Open-Meteo API response with rain

const now = new Date();
const mockWeatherResponse = {
  hourly: {
    time: [
      now.toISOString(),
      new Date(now.getTime() + 3600000).toISOString(),
      new Date(now.getTime() + 7200000).toISOString(),
      new Date(now.getTime() + 10800000).toISOString()
    ],
    precipitation: [0.5, 0.8, 0.2, 0.0],
    weathercode: [61, 63, 61, 3]
  }
};

return mockWeatherResponse;

// MOCK DATA: Calendar for Use Case 1
// Simulates Google Calendar API response

const mockCalendarResponse = {
  events: [
    {
      id: 'evt_1',
      summary: 'Team Standup',
      start: { dateTime: '2026-01-31T10:30:00+01:00' },
      end: { dateTime: '2026-01-31T11:00:00+01:00' },
      location: 'Bremen Office'
    },
    {
      id: 'evt_2',
      summary: 'Project Review',
      start: { dateTime: '2026-01-31T14:00:00+01:00' },
      end: { dateTime: '2026-01-31T15:00:00+01:00' },
      location: 'Bremen Office'
    }
  ]
};

return mockCalendarResponse;

// CONVERSION: Transport API Response → SimplifiedConnections
// Works with both mock and live data

const input = $input.first().json;
const journeys = input.journeys;

if (!journeys || journeys.length === 0) {
  throw new Error('No journeys found in transport data');
}

// Convert to ConnectionsAnswer format (full details)
const connectionsAnswer = {
  connections: journeys.map((journey, i) => {
    const leg = journey.legs[0];
    return {
      id: `conn_${i + 1}`,
      departure: leg.departure,
      arrival: leg.arrival,
      durationMinutes: Math.round((new Date(leg.arrival) - new Date(leg.departure)) / 60000),
      legs: [{
        mode: 'train',
        line: leg.line?.name || 'RE4',
        operator: leg.line?.operator?.name || 'DB Regio',
        from: { name: leg.origin?.name || 'Hamburg Hbf' },
        to: { name: leg.destination?.name || 'Bremen Hbf' },
        scheduledDeparture: leg.plannedDeparture,
        realtimeDeparture: leg.departure,
        scheduledArrival: leg.plannedArrival,
        realtimeArrival: leg.arrival,
        status: leg.cancelled ? 'CANCELLED' : (leg.departureDelay > 300 ? 'DELAYED' : 'ON_TIME'),
        delayMinutes: Math.round((leg.departureDelay || 0) / 60),
        remarks: leg.remarks?.map(r => r.text) || []
      }]
    };
  }),
  queryMeta: {
    realtimeUsed: true,
    generatedAt: new Date().toISOString()
  }
};

// Convert to SimplifiedConnections for AgentInfo
const simplifiedConnections = connectionsAnswer.connections.map(c => ({
  dep: new Date(c.departure).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' }),
  arr: new Date(c.arrival).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' }),
  line: c.legs[0].line,
  status: c.legs[0].status,
  delayMin: c.legs[0].delayMinutes || 0
}));

return {
  connectionsAnswer,
  connections: simplifiedConnections
};

// CONVERSION: Weather API Response → WeatherForecast
// Works with both mock and live data

const input = $input.first().json;
const hourly = input.hourly;

if (!hourly || !hourly.precipitation) {
  return { weatherForecast: null };
}

// Find first hour with significant precipitation (>0.1mm)
const rainStartIndex = hourly.precipitation.findIndex((p, i) => i < 6 && p > 0.1);

const weatherForecast = {
  rainStartsLocalTime: rainStartIndex >= 0 
    ? new Date(hourly.time[rainStartIndex]).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
    : null,
  condition: rainStartIndex >= 0 ? 'rain' : 'clear',
  // Additional details for UI
  precipitationMm: rainStartIndex >= 0 ? hourly.precipitation[rainStartIndex] : 0,
  weatherCode: rainStartIndex >= 0 ? hourly.weathercode[rainStartIndex] : hourly.weathercode[0]
};

return { weatherForecast };

// CONVERSION: Calendar API Response → nextMeetingLocalTime
// Works with both mock and live (Google Calendar) data

const input = $input.first().json;
const events = input.events || input.items || [];

if (!events || events.length === 0) {
  return {
    nextMeetingLocalTime: null,
    nextMeetingTitle: null,
    hasMeetingsToday: false
  };
}

// Sort events by start time
const sortedEvents = events
  .filter(e => e.start?.dateTime)
  .sort((a, b) => new Date(a.start.dateTime) - new Date(b.start.dateTime));

const nextEvent = sortedEvents[0];

if (!nextEvent) {
  return {
    nextMeetingLocalTime: null,
    nextMeetingTitle: null,
    hasMeetingsToday: false
  };
}

const meetingTime = new Date(nextEvent.start.dateTime);

return {
  nextMeetingLocalTime: meetingTime.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' }),
  nextMeetingTitle: nextEvent.summary || 'Meeting',
  nextMeetingLocation: nextEvent.location || null,
  hasMeetingsToday: sortedEvents.length > 0,
  totalMeetingsToday: sortedEvents.length
};

// BUILD: AgentInfo from all converted data sources
// Merges transport, weather, calendar, and user preferences

const webhookData = $('Webhook').first().json.body || {};
const transportData = $('Convert Transport Data').first().json;
const weatherData = $('Convert Weather Data').first().json;
const calendarData = $('Convert Calendar Data').first().json;

// Build complete AgentInfo
const agentInfo = {
  timeNow: webhookData.timeNow || new Date().toISOString(),

  route: webhookData.route || {
    from: 'Hamburg Hbf',
    to: 'Bremen Hbf',
    preferredLine: 'RE4'
  },

  // Simplified connections for decision making
  connections: transportData.connections,

  // User context (from request or defaults)
  userContext: {
    homeOfficeAllowed: webhookData.userContext?.homeOfficeAllowed ?? true,
    nextMeetingLocalTime: calendarData.nextMeetingLocalTime || webhookData.userContext?.nextMeetingLocalTime || null,
    avoidWaitingOutdoors: webhookData.userContext?.avoidWaitingOutdoors ?? true
  },

  // Weather forecast (optional)
  weatherForecast: weatherData.weatherForecast?.rainStartsLocalTime ? weatherData.weatherForecast : undefined,

  // Additional context for better decisions
  calendarContext: {
    nextMeetingTitle: calendarData.nextMeetingTitle,
    hasMeetingsToday: calendarData.hasMeetingsToday,
    totalMeetingsToday: calendarData.totalMeetingsToday
  }
};

// Also pass through the full ConnectionsAnswer for reference
return {
  agentInfo,
  connectionsAnswer: transportData.connectionsAnswer
};

// MOCK DECISION: Use Case 1 response (skip Gemini API)
// Returns the exact agent-decision.json from use_case_1_example

const mockDecision = {
  id: `dec_demo_${Date.now().toString().slice(-6)}`,
  decision: 'WORK_FROM_HOME_TEMPORARILY',
  confidence: 0.88,

  currentUpdates: [
    {
      type: 'weather',
      icon: 'rain',
      title: 'Weather update',
      message: 'Heavy rain for the next 30 minutes',
      severity: 'medium'
    },
    {
      type: 'transport',
      icon: 'train',
      title: 'RE4 status',
      message: 'The RE4 is cancelled at 07:34 and delayed by 12 minutes at 08:06',
      severity: 'high',
      line: 'RE4'
    }
  ],

  recommendation: {
    action: 'Start working from home',
    primaryInstruction: 'Take the RE4 at 08:34',
    recommendedDepartureTime: '08:34',
    icon: 'train',
    reasonShort: 'Earlier connections are cancelled or delayed.',
    reasonLong: 'Leaving now would cause waiting time with uncertain arrival. Starting in home office and taking the stable RE4 at 08:34 ensures a reliable commute and arrival before your 10:30 meeting.'
  },

  explanationShort: 'RE4 cancelled. Work from home and take the stable 08:34 connection.',
  explanationLong: 'Your usual RE4 at 07:34 is cancelled and the following RE4 is delayed. Weather conditions also make waiting unpleasant. Starting in home office and leaving at 08:34 avoids stress and still gets you to Bremen well before your first meeting.',

  uiHints: {
    highlightAction: true,
    playVoiceSummary: true,
    confidenceIndicator: 'high'
  },

  // Debug info
  _debug: {
    mode: 'demo',
    dataSource: 'mock',
    geminiCalled: false
  }
};

return mockDecision;

// PARSE: Gemini API response → AgentDecision

const geminiResponse = $input.first().json;

try {
  const text = geminiResponse.candidates[0].content.parts[0].text;
  const decision = JSON.parse(text);

  if (!decision.decision || !decision.recommendation || !decision.explanationShort) {
    throw new Error('Invalid decision structure from Gemini');
  }

  // Add debug info
  decision._debug = {
    mode: 'live',
    dataSource: 'gemini',
    geminiCalled: true
  };

  return decision;
} catch (error) {
  console.error('Gemini parse error:', error.message);

  // Fallback decision
  return {
    id: `dec_fallback_${Date.now()}`,
    decision: 'LEAVE_NOW',
    confidence: 0.5,
    currentUpdates: [{
      type: 'transport',
      icon: 'train',
      title: 'Status unavailable',
      message: 'Could not fetch current status',
      severity: 'medium'
    }],
    recommendation: {
      action: 'Check manually',
      primaryInstruction: 'Review transport status on DB app',
      recommendedDepartureTime: 'now',
      icon: 'train',
      reasonShort: 'Unable to generate recommendation',
      reasonLong: 'The system could not generate a recommendation. Please check the Deutsche Bahn app for current status.'
    },
    explanationShort: 'System unavailable. Check DB app.',
    explanationLong: 'Could not generate decision. Please check transport status manually.',
    uiHints: { highlightAction: false, playVoiceSummary: false, confidenceIndicator: 'low' },
    _debug: { mode: 'fallback', error: error.message }
  };
}
